CREATE TRIGGER gwg_onboarding_draft_drop_on_invite_closed AFTER UPDATE OF status, token_hash ON public.gwg_onboarding_invite FOR EACH ROW WHEN ((((new.status = 'CANCELLED'::public.gwg_invite_status) AND (old.status IS DISTINCT FROM new.status)) OR ((new.token_hash ~~ 'vernichtet-%'::text) AND (old.token_hash IS DISTINCT FROM new.token_hash)))) EXECUTE FUNCTION app.gwg_onboarding_draft_drop_on_invite_closed();
